INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "资治通鉴·卷256", "source_type": "primary", "author": "司马光等", "edition": "仓库电子文本；未核纸本。引文按原文保留，疑似转录讹字单独注明。", "url": "https://github.com/greed-216/histree/blob/fdc81a0b21a4c29dcfb4a4ecc9006df86ffe9248/resources/derived/tongjian/256.txt", "note": "卷256中和四年21段；原始电子文本与SHA-256见来源清单。", "id": "a38849fc-5d04-59ee-ae04-1830b68b7d1a"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "朱玫", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启元年条所见人物：朱玫。", "biography": null, "status": "draft", "id": "bb37d3e7-f348-51ea-bc68-8b4355399a19"}, {"name": "萧遘", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：萧遘。", "biography": null, "status": "draft", "id": "4eb0a98d-80ed-52f0-9e2c-2a84e77f2147"}, {"name": "裴澈", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：裴澈。", "biography": null, "status": "draft", "id": "218df366-f371-537f-8710-a07a8460f214"}, {"name": "郑昌图", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：郑昌图。", "biography": null, "status": "draft", "id": "e873d448-fba7-591c-8f89-710c5ad67716"}, {"name": "高骈", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年条记载的高骈，在此段中为受呈者。", "biography": null, "status": "draft", "id": "c4d5b35a-b520-57df-87da-baff9480b7e4"}, {"name": "吕用之", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年条记载的吕用之，在此段中为被指控者。", "biography": null, "status": "draft", "id": "cd08ae2a-9825-5636-a942-312bb29aed61"}, {"name": "夏侯潭", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：夏侯潭。", "biography": null, "status": "draft", "id": "b37a1e10-a563-5dbe-ad3d-3390fe15a1d2"}, {"name": "杨陟", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：杨陟。", "biography": null, "status": "draft", "id": "c3ca1369-9ab9-50c6-970e-8512a80b9d45"}, {"name": "郑杞", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：郑杞。", "biography": null, "status": "draft", "id": "56a0d2ee-e0d0-5ab8-8973-70182a87da27"}, {"name": "董瑾", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：董瑾。", "biography": null, "status": "draft", "id": "0ec89f74-dd87-559a-9808-154eeff3458a"}, {"name": "李昌符", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256中和四年条所见人物：李昌符。", "biography": null, "status": "draft", "id": "40f447e6-4770-5e94-9e87-b48375844b3d"}, {"name": "李煴", "aliases": ["嗣襄王煴"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：李煴。", "biography": null, "status": "draft", "id": "1cdc1b9d-e9a6-55fd-b6ea-016b483c2f3d"}, {"name": "王行瑜", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256中和四年条所见人物：王行瑜。", "biography": null, "status": "draft", "id": "65e50f4b-8971-5070-b043-77c6748c1fc0"}, {"name": "杨晟", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：杨晟。", "biography": null, "status": "draft", "id": "93faf005-49ad-5fd8-82c5-75a556805ef0"}, {"name": "杜让能", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：杜让能。", "biography": null, "status": "draft", "id": "e3eae55f-2032-5c76-905f-e480ad32ea69"}, {"name": "刘崇望", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：刘崇望。", "biography": null, "status": "draft", "id": "ffc52aae-093c-57ce-a03c-f416683079f6"}, {"name": "王重荣", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "晚唐河中节度使；882年朱温举同州归附，王重荣接纳并上奏。", "biography": "晚唐河中节度使；882年朱温举同州归附，王重荣接纳并上奏。", "status": "draft", "id": "fc935d86-e44a-538d-b21b-6e28a8604116"}, {"name": "李克用", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": 908, "description": "河东晋王，李存勖之父。908年去世，临终命李存勖继承军府。此处的晋不等于后来的后晋。", "biography": "河东晋王，李存勖之父。908年去世，临终命李存勖继承军府。此处的晋不等于后来的后晋。", "status": "draft", "id": "04af206e-fa86-581c-86b9-87a78a8d59a5"}, {"name": "盖寓", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：盖寓。", "biography": null, "status": "draft", "id": "dc2bf499-603a-5a8d-b566-14b9f5024667"}, {"name": "秦贤", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256中和四年条所见人物：秦贤。", "biography": null, "status": "draft", "id": "ca7ed1a7-1af6-567f-b170-8e77c7cc36fb"}, {"name": "朱温", "aliases": ["朱全忠", "朱晃", "梁太祖"], "era": "五代十国", "birth_year": null, "death_year": 912, "description": "后梁建立者。907年在大梁称帝，912年在宫廷政变中被杀。", "biography": "后梁建立者。907年在大梁称帝，912年在宫廷政变中被杀。", "status": "draft", "id": "0555e455-34d4-54ef-b93e-b0e6425018ab"}, {"name": "郭言", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：郭言。", "biography": null, "status": "draft", "id": "d890bf28-055c-53ab-a5fb-de04032e2f7b"}, {"name": "杨守亮", "aliases": ["訾亮"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：杨守亮。", "biography": null, "status": "draft", "id": "794556be-c340-512f-923f-61f100db55df"}, {"name": "杨守信", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：杨守信。", "biography": null, "status": "draft", "id": "3162cc98-31d1-5f1c-8d13-86cc7912a541"}, {"name": "杨复光", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：杨复光。", "biography": null, "status": "draft", "id": "0b8d9e1a-c1f4-5af3-89a3-39bbc87ff762"}, {"name": "杨复恭", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256中和四年条所见人物：杨复恭。", "biography": null, "status": "draft", "id": "d84e65f4-4bf5-58ad-a8c6-d69729edbc51"}, {"name": "周岳", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：周岳。", "biography": null, "status": "draft", "id": "9485af1c-62f2-5a2e-9aa9-f6dba9c278ed"}, {"name": "闵勖", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：闵勖。", "biography": null, "status": "draft", "id": "958d9b44-521e-5dc8-8c00-ec9a8321bed6"}, {"name": "黄皓", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：黄皓。", "biography": null, "status": "draft", "id": "db50e697-04e6-5da3-9489-0fd274bf7f2f"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "朱玫在襄王煴名下大行封拜", "start_year": 886, "end_year": 886, "time_original": "光启二年五月", "dynasty": "唐", "description": "朱玫把萧遘改任太子太保，自加侍中及盐铁、转运等职，并安排裴澈、郑昌图、高骈、吕用之等人职务，以争取诸藩镇。", "phases": [], "location_name": "京师及诸镇", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "03df63dd-6ff8-5bb9-a991-666da53cdab4"}, {"title": "朱玫遣使宣谕河北、江淮", "start_year": 886, "end_year": 886, "time_original": "光启二年五月", "dynasty": "唐", "description": "朱玫遣夏侯潭赴河北、杨陟赴江淮宣谕；《通鉴》记不少藩镇受其命，高骈又上笺劝进。", "phases": [], "location_name": "河北、江淮", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "53862cb6-041c-5355-9c06-4c461eb08077"}, {"title": "吕用之在淮南自建幕府并扩张权力", "start_year": 886, "end_year": 886, "time_original": "光启二年五月后条；确日未载", "dynasty": "唐", "description": "吕用之建牙开幕，逼高骈亲信和能任事将校归从自己，行事不再请示高骈；高骈暗中想夺其权而未能。", "phases": [], "location_name": "淮南", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "126fafd3-8c9d-591f-bb3e-a8a783d902f8"}, {"title": "郑杞、董瑾为吕用之作密信", "start_year": 886, "end_year": 886, "time_original": "前事次日；确月日未载", "dynasty": "唐", "description": "吕用之因高骈疑忌而询问郑杞、董瑾；次日二人写密信交给吕用之，信中内容原文未载。", "phases": [], "location_name": "淮南", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "1b1117ca-a064-5c7b-81b6-dcd40e850127"}, {"title": "萧遘称病归永乐", "start_year": 886, "end_year": 886, "time_original": "光启二年五月后条；具体日未载", "dynasty": "唐", "description": "萧遘称病，返回永乐。", "phases": [], "location_name": "永乐", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "57b7bef4-a9c2-5f2d-837b-27fe3252da37"}, {"title": "李昌符与朱玫分裂，向兴元通表", "start_year": 886, "end_year": 886, "time_original": "光启二年五月后条；具体日未载", "dynasty": "唐", "description": "李昌符原与朱玫共同谋立襄王煴，后因朱玫专权不满，不受其官，转向兴元上表；朝廷加李昌符检校司徒。", "phases": [], "location_name": "凤翔、兴元", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "ed8dca60-d5bc-5cf5-a54b-ab16e249732d"}, {"title": "王行瑜奉朱玫命追车驾，占凤州", "start_year": 886, "end_year": 886, "time_original": "光启二年五月后条；具体日未载", "dynasty": "唐", "description": "朱玫遣王行瑜率军追车驾。杨晟数次战斗后弃散关，王行瑜进屯凤州。", "phases": [], "location_name": "散关、凤州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "1fbb5a07-7a14-53cc-bbb7-e8562743eb60"}, {"title": "贡赋多往长安，兴元行在粮食不足", "start_year": 886, "end_year": 886, "time_original": "光启二年五月后条；具体日未载", "dynasty": "唐", "description": "《通鉴》记诸道贡赋多送长安而非兴元，随驾官员和卫士缺粮。", "phases": [], "location_name": "兴元、长安", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "d96426f7-f7d2-5193-81e0-cf325d615a51"}, {"title": "刘崇望赴河中劝王重荣归顺", "start_year": 886, "end_year": 886, "time_original": "光启二年五月后条；具体日未载", "dynasty": "唐", "description": "杜让能建议遣使劝王重荣归朝；皇帝遣刘崇望赍诏往河中。王重荣听命，上表称献绢十万匹并请求讨朱玫。", "phases": [], "location_name": "兴元、河中", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "e52bec70-f1ab-5881-8093-f7b5424e32bc"}, {"title": "襄王煴使者向李克用谎称僖宗驾崩", "start_year": 886, "end_year": 886, "time_original": "光启二年戊戌；月份本段未明", "dynasty": "唐", "description": "襄王煴遣使赐李克用诏，诏中声称皇帝途中驾崩、自己已受册；这是襄王方面的说辞。朱玫也致书李克用。", "phases": [], "location_name": "晋阳", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "eb274747-c0ab-54c9-8472-bfaedc9a8c2b"}, {"title": "李克用拒襄王煴，声讨朱玫", "start_year": 886, "end_year": 886, "time_original": "收到诏书之后；具体日未载", "dynasty": "唐", "description": "盖寓劝李克用讨朱玫、黜襄王煴；李克用焚诏、拘使，并向邻道发檄声讨朱玫。", "phases": [], "location_name": "晋阳", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "4e8679c0-402d-53dd-9c7f-6c515b4ca895"}, {"title": "朱全忠在尉氏南击败秦贤", "start_year": 886, "end_year": 886, "time_original": "光启二年五月后条；具体日未载", "dynasty": "唐", "description": "秦贤攻宋、汴，朱全忠在尉氏南击败秦贤部。", "phases": [], "location_name": "尉氏南", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "e3335792-3f98-5bf5-a4a7-ee9c1e1e3f92"}, {"title": "朱全忠遣郭言攻蔡州", "start_year": 886, "end_year": 886, "time_original": "光启二年癸巳；月份本段未明", "dynasty": "唐", "description": "朱全忠遣都将郭言率步骑军攻蔡州。", "phases": [], "location_name": "蔡州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "3b639177-d721-51b4-962e-083f00e4c60a"}, {"title": "杨守亮受命为金商节度使并讨朱玫", "start_year": 886, "end_year": 886, "time_original": "光启二年六月", "dynasty": "唐", "description": "朝廷任杨守亮为金商节度、京畿制置使，令其出金州与王重荣、李克用共讨朱玫。", "phases": [], "location_name": "金州、金商", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "9c084292-5df9-5895-98f9-87f13bb7bb97"}, {"title": "李克用上表请合力讨朱玫", "start_year": 886, "end_year": 886, "time_original": "光启二年六月条；具体日未载", "dynasty": "唐", "description": "李克用遣使上表，称将渡河除逆、迎回车驾，并请朝廷令诸道协力；皇帝把表章示从官和山南诸镇。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "19334fc9-bb40-5bd7-9766-45f75d102c01"}, {"title": "朝廷劝李克用暂缓对付朱全忠", "start_year": 886, "end_year": 886, "time_original": "收到李克用表章后；具体日未载", "dynasty": "唐", "description": "李克用表章仍提朱全忠；朝廷遣杨复恭致书，表示待三辅平定后另有安排。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "1944ca99-847b-5730-8d49-e7f00d5530e2"}, {"title": "周岳攻取潭州，黄皓杀闵勖后亦被杀", "start_year": 886, "end_year": 886, "time_original": "光启二年六月条；具体日未载", "dynasty": "唐", "description": "衡州刺史周岳攻潭州。钦化节度使闵勖邀黄皓入城共守，黄皓杀闵勖；周岳攻下城，擒杀黄皓。", "phases": [], "location_name": "潭州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "4f3cba00-2f71-55eb-841f-3f7b568235fd"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

